const b = $json.body || $json;
const planesOk = new Set(['basico', 'presencia', 'completo']);
const plan = String(b.plan || '').trim().toLowerCase();
const cliente = String(b.cliente || b.slug || '').trim();
const nombre = String(b.nombre || '').trim();
const whatsapp = String(b.whatsapp || b.telefono || '').trim();
const jobAudit = String(b.jobId || b.job_audit || '').trim();
if (!planesOk.has(plan)) {
  return [{ json: { ok: false, error: 'plan inválido', planes: [...planesOk], sistema: '06-auditorias-locales' } }];
}
if (!cliente && !whatsapp) {
  return [{ json: { ok: false, error: 'falta cliente o whatsapp' } }];
}
return [{ json: {
  ok: true,
  sistema: '06-auditorias-locales',
  etapa: 'upsell_plan',
  leadId: `LP-${Date.now()}`,
  plan,
  cliente,
  nombre,
  whatsapp,
  jobAudit,
  status: 'interes_registrado',
  todo: 'TODO: avisar por Wasap + crear carpeta clientes/{slug}/proyectos/…',
  at: new Date().toISOString()
}}];
